        for chunk in chunks.values()
    ):
        raise APIError(500, "citation_metadata_missing", "Trusted citation metadata is unavailable")
    return chunks

def _citation(self, block: ContextBlock) -> QACitation:
    return QACitation(
        chunk_id=block.chunk_id,
        source_file=block.citation.source_file,
        symbol_name=block.citation.symbol_name,
        qualified_name=block.citation.qualified_name,
        start_line=block.citation.start_line,
        end_line=block.citation.end_line,
    )

def validate_pinned_repository(repository: Path, expected_commit: str) -> str:
    """Require an exact Git commit and a clean tracked/untracked worktree."""
    commit = _git(repository, "rev-parse", "HEAD")
    if commit != expected_commit:
        raise RepositoryValidationError(
            f"repository commit mismatch: expected {expected_commit}, got {commit}"
        )
    if _git(repository, "status", "--porcelain", "--untracked-files=normal"):
        raise RepositoryValidationError("repository worktree must be clean before indexing")
    return commit

def index(self, repository_path: str, project_name: str | None, override: EmbeddingProviderOverride | None) -> dict[str, Any]:
    if not self.index_lock.acquire(blocking=False):
        raise APIError(409, "indexing_in_progress", "Another indexing operation is already running")
    try:
        return self._index_pipeline(Path(repository_path), project_name, override)
    finally:
        self.index_lock.release()

